//! Cargo-driven `inetcpl.cpl` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is inetcpl-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("inetcpl-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "sdk/lib/delayimp/libdelayimp_rust.a", "engine:oldnames"],
        "x86_64" => &["engine:wine", "sdk/lib/delayimp/libdelayimp_rust.a", "engine:oldnames"],
        "aarch64" => &["engine:wine", "sdk/lib/delayimp/libdelayimp_rust.a", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("inetcpl-rust")
        .resource_from_rc("dll/cpl/inetcpl/inetcpl.rc", "inetcpl_res")
        .spec2def("dll/cpl/inetcpl/inetcpl.spec", "inetcpl.cpl")
        .spec_stubs()
        .delay_import_lib("dll/win32/cryptui/cryptui.spec", "cryptui.dll", "cryptui")
        .delay_import_lib("dll/win32/wininet/wininet.spec", "wininet.dll", "wininet")
        .delay_import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .delay_import_lib("dll/win32/urlmon/urlmon.spec", "urlmon.dll", "urlmon")
        .delay_import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
